  &reftitle.examples;

   Exemple avec Yaf_View_Simple::render


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function detailAction()
    {
        /* rend le template et post-traite le résultat */
        $html = $this->getView()->render("product/detail.phtml", array(
            "name"  => "Yaf in Action",
            "price" => "29.90",
        ));

        $this->getResponse()->setBody($html);
        return false; // désactive le rendu automatique
    }
}
?>




   Exemple de template


<h1><?php echo $name; ?></h1>
<p>Prix : <?php echo $price; ?> EUR</p>


